# SPDX-License-Identifier: MIT
"""Generate the CMake bootstrap from the indexed infrastructure pin (AR-2)."""

import subprocess
import tomllib
from pathlib import Path

from .metadata import REVISION, InputError

SYNC = "python3 -m infra.pico_tooling sync"
BOOTSTRAP = """\
# SPDX-License-Identifier: MIT
# Generated by pico-tooling from the infra pin; run {sync}.
# Include before project(). A parent's family context wins; otherwise this
# checkout's infra/, otherwise one fetch of the pinned infrastructure chain.
set(PICO_FAMILY_INFRA_REPOSITORY "{repository}")
set(PICO_FAMILY_INFRA_REVISION "{revision}")
set(PICO_FAMILY_INFRA_VERSION "{version}")
get_property(_pico_family_root GLOBAL PROPERTY PICO_FAMILY_ROOT)
if(NOT _pico_family_root)
    if(EXISTS "${{CMAKE_CURRENT_LIST_DIR}}/../infra/cmake/pico_family.cmake")
        set(_pico_family_root "${{CMAKE_CURRENT_LIST_DIR}}/../infra")
    else()
        include(FetchContent)
        FetchContent_Declare(pico_tooling
            GIT_REPOSITORY "${{PICO_FAMILY_INFRA_REPOSITORY}}"
            GIT_TAG "${{PICO_FAMILY_INFRA_REVISION}}"
            SOURCE_SUBDIR do-not-add-subdirectory)
        FetchContent_MakeAvailable(pico_tooling)
        set(_pico_family_root "${{pico_tooling_SOURCE_DIR}}")
    endif()
endif()
include("${{_pico_family_root}}/cmake/pico_family.cmake")
_pico_family_context("${{_pico_family_root}}" "${{PICO_FAMILY_INFRA_REVISION}}"
    "${{PICO_FAMILY_INFRA_VERSION}}")
unset(_pico_family_root)
"""


def version():
    """Read the pinned family's release version from its build metadata (AR-6)."""
    path = Path(__file__).resolve().parents[1] / "pyproject.toml"
    try:
        return tomllib.loads(path.read_text(encoding="utf-8"))["project"]["version"]
    except (OSError, UnicodeError, ValueError, KeyError) as error:
        raise InputError(f"cannot read the family version: {error}") from error


def infra_revision(root):
    """Return the infra Gitlink recorded in the index, the generated pin's source."""
    try:
        row = subprocess.run(
            ["git", "-C", str(root), "ls-files", "--stage", "--", "infra"],
            capture_output=True, text=True, check=True,
        ).stdout.strip()
    except (OSError, subprocess.CalledProcessError) as error:
        raise InputError(f"cannot read the infra pin: {error}") from error
    fields = row.split()
    if len(fields) < 2 or fields[0] != "160000" or not REVISION.fullmatch(fields[1]):
        raise InputError("infra is not a pinned submodule in the index")
    return fields[1]


def files(root, data):
    return {
        "cmake/pico_family_bootstrap.cmake": BOOTSTRAP.format(
            sync=SYNC, repository=data["infra"]["repository"],
            revision=infra_revision(root), version=version(),
        ),
    }
